TOOL.Category="GRM";TOOL.Name="#tool.grm_property.name";TOOL.Command=nil;TOOL.ConfigName=""
if CLIENT then language.Add("tool.grm_property.name","GRM Недвижимость");language.Add("tool.grm_property.desc","Выбор дверей для помещения/здания");language.Add("tool.grm_property.0","ЛКМ: добавить/убрать дверь • ПКМ: открыть управление • R: очистить выбор")end
function TOOL:LeftClick(tr)if CLIENT then return true end;local p=self:GetOwner();if not(GRM.Property and GRM.Property.CanAdmin and GRM.Property.CanAdmin(p)and IsValid(tr.Entity))then return false end;local ok,on,id=GRM.Property and GRM.Property.ToggleDoorSelection and GRM.Property.ToggleDoorSelection(p,tr.Entity);if ok then p:ChatPrint("[Недвижимость] "..(on and"Добавлена дверь: "or"Убрана дверь: ")..tostring(id))end;return ok==true end
function TOOL:RightClick()if CLIENT then return true end;local p=self:GetOwner();if GRM.Property and GRM.Property.CanAdmin and GRM.Property.CanAdmin(p)and GRM.Property and GRM.Property.OpenAdmin then GRM.Property.OpenAdmin(p)return true end return false end
function TOOL:Reload()if CLIENT then return true end;local p=self:GetOwner();if GRM.Property and GRM.Property.CanAdmin and GRM.Property.CanAdmin(p)and GRM.Property then GRM.Property.Selections=GRM.Property.Selections or{};GRM.Property.Selections[p]={};p:ChatPrint("[Недвижимость] Выбор дверей очищен.")return true end return false end
function TOOL.BuildCPanel(panel)panel:Help("1. Отметьте все двери помещения ЛКМ.");panel:Help("2. ПКМ откроет большое меню.");panel:Help("3. Нажмите «Создать из отмеченных дверей».");panel:Button("Открыть управление","grm_property_admin")end
